-- Progressive disclosure (d28 batch317; docs/DISCLOSURE.md): the kit each team (force) sees grows with its research,
-- buildings, encounters and habits. The conditions are disclosure_units.lua (generated by tools/disclosure/build.py from
-- tools/disclosure/rules.py): per unit g, the world flags it needs (all), and a, the atoms that open it (any).
--
-- Modes (storage, set by the operator call disclosure_set; tools/start-team.sh from POG_DISCLOSURE):
--   off      (default) everything open, no state kept: world n as before;
--   observe  the atoms are met and the unlocks logged as in a disclosure run, nothing filtered or said to agents;
--   filter   describe, fh help and the brief show the force's open set; a call to a unit not yet open runs, undocumented
--            (refuse=true: refused naming its condition; Nick d28 15:47: "probably ok to run"); each unlock reaches the
--            force's agents once as a
--            `new:` line on their next reply.
-- Per force: the player force in main (force_of, forces in runtime.lua), a team's force with several teams.
-- Costs (iMac copy, world n's save of d28 13:20): the sweep of one force 0.10-0.14 ms every 600 ticks, reading only
-- atoms not met yet; a counter 28 ns; an open lookup 86 ns per 1000.
return function(api)
  local M = {operator={}, schema={}, handlers={}}
  local U = api.units
  local HOUR = 216000
  local MAX_KEYS, MAX_LOG = 64, 64
  -- calls never gated: the host's own (fh help, sleeps), and actions the rules keep from agents (attach, ...)
  local HOST = {describe=true, disclosure=true, sleep_check=true, bridge_status=true, lookahead=true}

  local function root()
    local s = api.state()
    s.disclosure = s.disclosure or {mode='off', refuse=false, forces={}}
    return s.disclosure
  end
  function M.mode()
    local d = api.state().disclosure
    return d and d.mode or 'off'
  end

  -- The atoms the units name, by kind; each habit or scale key's thresholds.
  local atoms, thresholds = {}, {}
  local function note(list)
    for _, a in ipairs(list) do
      atoms[a] = true
      local key, n = a:match('^(%a+:[%w_%-]+):(%d+)$')
      if key and (a:sub(1, 6) == 'habit:' or a:sub(1, 6) == 'scale:') then
        thresholds[key] = thresholds[key] or {}
        thresholds[key][tonumber(n)] = true
      end
    end
  end
  for _, c in pairs(U.actions) do note(c.a) end
  for _, t in pairs(U.args) do for _, c in pairs(t) do note(c.a) end end
  for _, c in pairs(U.docs) do note(c.a) end
  for _, c in pairs(U.brief) do note(c.a) end
  local TOTAL = {actions=0, args=0, docs=0, brief=0}
  for name, c in pairs(U.actions) do
    local never = false
    for _, a in ipairs(c.a) do if a == 'never' then never = true end end
    if not never then TOTAL.actions = TOTAL.actions + 1 end
  end
  for _, t in pairs(U.args) do for _ in pairs(t) do TOTAL.args = TOTAL.args + 1 end end
  for _ in pairs(U.docs) do TOTAL.docs = TOTAL.docs + 1 end
  for _ in pairs(U.brief) do TOTAL.brief = TOTAL.brief + 1 end
  M.TOTAL = TOTAL

  local function fstate(force)
    local d = root()
    local f = d.forces[force.name]
    if not f then
      f = {met={}, counts={}, keys={}, rev=0, log={}, told={}, since=game.tick}
      d.forces[force.name] = f
    end
    return f
  end
  M.fstate = fstate

  -- The world flags (fixed for the run): computed, then what disclosure_set gave.
  function M.world(force)
    local d = root()
    local w = {}
    local mods = script.active_mods or {}
    w.space_age = mods['space-age'] ~= nil
    w.quality = mods['quality'] ~= nil
    local nauvis = game.get_surface('nauvis')
    w.enemies = nauvis ~= nil and not nauvis.peaceful_mode and not nauvis.no_enemies_mode
    w.team = (api.team_size and api.team_size(force) or 1) > 1
    for k, v in pairs(d.world or {}) do w[k] = v end
    return w
  end

  local function met(f, a, action)
    if a == 'start' then return true end
    if a == 'never' or a == 'self' then return false end
    local key, n = a:match('^(%a+:[%w_%-]+):(%d+)$')
    if key and (a:sub(1, 6) == 'habit:' or a:sub(1, 6) == 'scale:') then
      if key == 'habit:refused' and action then key = 'habit:refused:' .. action end
      return (f.counts[key] or 0) >= tonumber(n)
    end
    return f.met[a] ~= nil
  end
  local function open(f, c, world, action)
    for _, g in ipairs(c.g) do if not world[g] then return false end end
    if #c.a == 0 then return true end
    for _, a in ipairs(c.a) do if a == 'never' then return false end end
    for _, a in ipairs(c.a) do if met(f, a, action) then return true end end
    return false
  end
  M.cond_open = open

  -- The force's open set, kept per revision (not in storage: rebuilt after a load).
  local cache = {}
  function M.open_set(force)
    local f = fstate(force)
    local c = cache[force.name]
    if c and c.rev == f.rev then return c end
    local world = M.world(force)
    c = {rev=f.rev, actions={}, args={}, docs={}, brief={}, world=world}
    for name, u in pairs(U.actions) do if open(f, u, world, name) then c.actions[name] = true end end
    for action, t in pairs(U.args) do
      c.args[action] = {}
      for arg, u in pairs(t) do if open(f, u, world, action) then c.args[action][arg] = true end end
    end
    for id, u in pairs(U.docs) do if open(f, u, world) then c.docs[id] = true end end
    for id, u in pairs(U.brief) do if open(f, u, world) then c.brief[id] = true end end
    cache[force.name] = c
    return c
  end
  function M.action_open(force, action)
    if M.mode() ~= 'filter' or not U.actions[action] then return true end
    return M.open_set(force).actions[action] == true
  end
  function M.arg_open(force, action, arg)
    if M.mode() ~= 'filter' then return true end
    local t = U.args[action]
    if not t or not t[arg] then return true end
    return M.open_set(force).args[action][arg] == true
  end

  -- A new atom or a threshold crossed: the revision grows and the units it opened are logged.
  local function bump(force, f, by)
    local before = M.open_set(force)
    f.rev = f.rev + 1
    local after = M.open_set(force)
    local entry = {rev=f.rev, tick=game.tick, by=by, actions={}, args=0, docs=0}
    for name in pairs(after.actions) do if not before.actions[name] then entry.actions[#entry.actions+1] = name end end
    table.sort(entry.actions)
    for action, t in pairs(after.args) do
      for arg in pairs(t) do if not before.args[action][arg] then entry.args = entry.args + 1 end end
    end
    for id in pairs(after.docs) do if not before.docs[id] then entry.docs = entry.docs + 1 end end
    if #entry.actions > 0 or entry.args > 0 or entry.docs > 0 then
      f.log[#f.log+1] = entry
      if #f.log > MAX_LOG then table.remove(f.log, 1) end
    end
  end
  function M.mark(force, atom)
    if M.mode() == 'off' or not atoms[atom] then return end
    local f = fstate(force)
    if f.met[atom] then return end
    f.met[atom] = game.tick
    bump(force, f, atom)
  end
  -- A counter to a value: the revision grows when it crosses a threshold some unit names.
  local function set_count(force, f, key, value, tkey)
    local old = f.counts[key] or 0
    if value <= old then return end
    f.counts[key] = value
    local ts = thresholds[tkey or key]
    if not ts then return end
    for n in pairs(ts) do
      if old < n and value >= n then bump(force, f, key .. ':' .. n); return end
    end
  end
  -- A keyed habit (per recipe, per container, per call shape): its kind's count is the largest key's.
  local function add_keyed(force, f, kind, sub, by)
    f.keys[kind] = f.keys[kind] or {}
    local t = f.keys[kind]
    if t[sub] == nil then
      local n = 0
      for _ in pairs(t) do n = n + 1 end
      if n >= MAX_KEYS then
        local low, lowk
        for k, v in pairs(t) do if not low or v < low then low, lowk = v, k end end
        t[lowk] = nil
      end
    end
    t[sub] = (t[sub] or 0) + by
    set_count(force, f, 'habit:' .. kind, t[sub])
  end
  local function add(force, f, kind, by)
    set_count(force, f, 'habit:' .. kind, (f.counts['habit:' .. kind] or 0) + by)
  end

  -- Habits: each agent call, counted after it ran (runtime M.dispatch).
  local ACTS = {craft=true, build=true, mine=true, transfer=true, collect=true, feed=true, refuel=true, move_to=true,
    walk=true, pickup=true, rotate=true, deconstruct=true, configure=true, place_ghosts=true}
  local function is_belt(name) return type(name) == 'string' and name:find('transport%-belt$') ~= nil end
  local function is_pole(name)
    return type(name) == 'string' and (name:find('electric%-pole$') ~= nil or name == 'substation')
  end
  function M.count(request, ok, result, force, from)
    if M.mode() == 'off' or type(request) ~= 'table' or request.operator == true or request.reader ~= nil then return end
    local action, args = request.action, type(request.args) == 'table' and request.args or {}
    if type(action) ~= 'string' or args.peek == true then return end
    local f = fstate(force)
    if not ok then
      if type(result) == 'string' and result:find('is not available yet', 1, true) then return end
      set_count(force, f, 'habit:refused:' .. action, (f.counts['habit:refused:' .. action] or 0) + 1, 'habit:refused')
      set_count(force, f, 'habit:refused', (f.counts['habit:refused'] or 0) + 1)
      if action == 'build' or action == 'place_ghosts' or action == 'mine' then add(force, f, 'refused_builds', 1) end
      return
    end
    if action == 'craft' and type(args.recipe) == 'string' then
      add_keyed(force, f, 'hand_crafts', args.recipe, tonumber(args.count) or 1)
    elseif action == 'build' then
      local entries = type(args.builds) == 'table' and args.builds or {{item=args.item}}
      local belts, poles = 0, 0
      for _, e in ipairs(entries) do
        local item = type(e) == 'table' and (e.item or e.entity or e.name) or args.item
        if is_belt(item) then belts = belts + 1 end
        if is_pole(item) then poles = poles + 1 end
      end
      if belts > 0 then add(force, f, 'hand_belts', belts) end
      if poles > 0 then add(force, f, 'hand_poles', poles) end
    elseif action == 'feed' or action == 'refuel' then
      add(force, f, 'hand_feeds', 1)
    elseif action == 'transfer' and type(args.position) == 'table' then
      local x, y = tonumber(args.position.x or args.position[1]), tonumber(args.position.y or args.position[2])
      if x and y then add_keyed(force, f, 'chest_moves', math.floor(x) .. ',' .. math.floor(y), 1) end
    elseif (action == 'move_to' or action == 'walk') and type(args.position) == 'table' and from then
      local x, y = tonumber(args.position.x or args.position[1]), tonumber(args.position.y or args.position[2])
      if x and y then
        local dx, dy = x - from.x, y - from.y
        add(force, f, 'walked', math.floor(math.sqrt(dx * dx + dy * dy)))
      end
    elseif action == 'sleep' or action == 'wait_ticks' or action == 'wait_until' then
      add(force, f, 'sleeps', 1)
    elseif action == 'board_post' then
      add(force, f, 'board_items', 1)
    end
    if ACTS[action] then
      local names = {}
      for k in pairs(args) do if k ~= 'peek' and k ~= 'helper' then names[#names+1] = tostring(k) end end
      table.sort(names)
      local shape = action .. '|' .. table.concat(names, ',')
      f.keys.repeats = f.keys.repeats or {}
      local r = f.keys.repeats[shape]
      if r and game.tick - r.tick <= 36000 then r.n, r.tick = r.n + 1, game.tick
      else
        local n = 0
        for _ in pairs(f.keys.repeats) do n = n + 1 end
        if n >= MAX_KEYS then f.keys.repeats = {} end
        r = {n=1, tick=game.tick}
        f.keys.repeats[shape] = r
      end
      set_count(force, f, 'habit:repeat_calls', r.n)
    end
  end

  -- Engine events (runtime.lua on_event): the force's first attack, loss, death, enemies of a kind, research, freight.
  local E = defines.events
  local pending_fight = true
  local function team_force(force) return force and force.valid and api.is_team(force) end
  local function enemy_kinds(force, e)
    if not (e and e.valid) then return end
    local name, etype = e.name, e.type
    M.mark(force, 'event:enemy_seen')
    if name:find('spitter') or name == 'medium-biter' or name == 'big-biter' or name == 'behemoth-biter' then
      M.mark(force, 'event:spitters')
    end
    if etype == 'turret' then M.mark(force, 'event:worms') end
    if name:find('demolisher') then M.mark(force, 'event:demolishers') end
    if name:find('wriggler') or name:find('strafer') or name:find('stomper') or name:find('pentapod') then
      M.mark(force, 'event:pentapods')
    end
  end
  function M.on_event(event)
    if M.mode() == 'off' then return end
    local name = event.name
    if name == E.on_research_finished then
      local r = event.research
      if r and r.valid and team_force(r.force) then M.mark(r.force, 'research:' .. r.name) end
    elseif name == E.on_entity_damaged or name == E.on_entity_died then
      if not pending_fight then return end
      local e = event.entity
      if not (e and e.valid) then return end
      local ef, by = e.force, event.force
      if team_force(ef) then
        local cause = event.cause
        if name == E.on_entity_died and e.type == 'character' then M.mark(ef, 'event:died') end
        if e.surface.platform then
          if cause == nil or (cause.valid and cause.type == 'asteroid') then M.mark(ef, 'event:asteroids') end
        elseif by and by.name == 'enemy' then
          M.mark(ef, 'event:attacked')
          if name == E.on_entity_died and e.type ~= 'character' then M.mark(ef, 'event:loss') end
          enemy_kinds(ef, cause)
        end
      elseif ef and ef.name == 'enemy' and by and team_force(by) then
        enemy_kinds(by, e)
      end
    elseif name == E.on_unit_group_finished_gathering then
      for _, force in ipairs(api.forces()) do M.mark(force, 'event:pollution_attack'); M.mark(force, 'event:enemy_seen') end
    elseif name == E.on_cargo_pod_finished_descending then
      local pod = event.cargo_pod
      if pod and pod.valid and team_force(pod.force) then M.mark(pod.force, 'event:freight') end
    end
  end

  -- The slow sweep (every 600 ticks, runtime.lua tick): only atoms not met yet are read.
  local SCALE_NAMES = {
    machines={'assembling-machine-1', 'assembling-machine-2', 'assembling-machine-3', 'stone-furnace', 'steel-furnace',
      'electric-furnace', 'chemical-plant', 'oil-refinery', 'centrifuge', 'foundry', 'electromagnetic-plant',
      'biochamber', 'cryogenic-plant', 'recycler', 'crusher'},
    labs={'lab', 'biolab'}, drills={'burner-mining-drill', 'electric-mining-drill', 'big-mining-drill'},
    belts={'transport-belt', 'fast-transport-belt', 'express-transport-belt', 'turbo-transport-belt'},
    inserters={'burner-inserter', 'inserter', 'long-handed-inserter', 'fast-inserter', 'bulk-inserter', 'stack-inserter'},
    turrets={'gun-turret', 'laser-turret', 'flamethrower-turret', 'rocket-turret', 'railgun-turret', 'tesla-turret',
      'artillery-turret'},
  }
  local known = {}
  local function exists(name)
    if known[name] == nil then known[name] = prototypes.entity[name] ~= nil end
    return known[name]
  end
  local function count_of(force, names)
    local n = 0
    for _, name in ipairs(names) do if exists(name) then n = n + force.get_entity_count(name) end end
    return n
  end
  local function pending(f, key)
    local ts = thresholds[key]
    if not ts then return false end
    for n in pairs(ts) do if (f.counts[key] or 0) < n then return true end end
    return false
  end
  -- The atoms the sweep reads, parsed once: {atom, kind, rest, names (built)}.
  local SWEPT
  local function swept()
    if SWEPT then return SWEPT end
    SWEPT = {}
    for a in pairs(atoms) do
      local kind, rest = a:match('^(%a+):(.*)$')
      if kind == 'research' or kind == 'built' or kind == 'arrived' or kind == 'event' then
        local names
        if kind == 'built' then
          names = {}
          for name in rest:gmatch('[^|]+') do names[#names+1] = name end
        end
        SWEPT[#SWEPT+1] = {a=a, kind=kind, rest=rest, names=names}
      end
    end
    table.sort(SWEPT, function(x, y) return x.a < y.a end)
    return SWEPT
  end
  -- part: 0 research, 1 buildings, 2 scale counts, 3 places and events (one part a sweep, each every 2400 ticks); nil:
  -- all four (disclosure_set, tests)
  local PART = {research=0, built=1, arrived=3, event=3}
  function M.sweep_force(force, part)
    local f = fstate(force)
    local fight = false
    -- read once a sweep: the technologies table, the force's characters (each a few API reads)
    local techs, chars
    local function characters()
      chars = chars or api.characters(force)
      return chars
    end
    for _, w in ipairs(swept()) do
      local a = w.a
      if not f.met[a] and (part == nil or PART[w.kind] == part) then
        local kind, rest = w.kind, w.rest
        if kind == 'research' then
          techs = techs or force.technologies
          local t = techs[rest]
          if t and t.researched then M.mark(force, a) end
        elseif kind == 'built' then
          for _, name in ipairs(w.names) do
            if exists(name) and force.get_entity_count(name) > 0 then M.mark(force, a); break end
          end
        elseif kind == 'arrived' then
          for _, pl in pairs(force.platforms) do
            if pl.valid and pl.space_location and pl.space_location.name == rest then M.mark(force, a); break end
          end
          if not f.met[a] then
            for _, c in ipairs(characters()) do
              if c.valid and c.surface.name == rest then M.mark(force, a); break end
            end
          end
        elseif a == 'event:second_surface' then
          if next(force.platforms) ~= nil then M.mark(force, a) end
          for _, c in ipairs(characters()) do
            if not f.met[a] and c.valid and c.surface.name ~= 'nauvis' then M.mark(force, a) end
          end
        elseif a == 'event:spoiled' then
          for _, s in pairs(game.surfaces) do
            if force.get_item_production_statistics(s).get_input_count('spoilage') > 0 then M.mark(force, a); break end
          end
        elseif a == 'event:resource_depleted' or a == 'event:low_power' then
          local c = api.push_groups and api.push_groups(force)
          for _, g in ipairs(c and c.groups or {}) do
            local k = type(g.kind) == 'string' and g.kind or ''
            if a == 'event:resource_depleted' and k:sub(1, 11) == 'out_of_ore.' then M.mark(force, a); break end
            if a == 'event:low_power' and (k == 'low_power' or k == 'no_power') then M.mark(force, a); break end
          end
        elseif a == 'event:enemy_seen' then
          fight = true
          for _, c in ipairs(characters()) do
            if c.valid and c.surface.count_entities_filtered{position=c.position, radius=64, force='enemy', limit=1} > 0 then
              M.mark(force, a); break
            end
          end
        elseif kind == 'event' then
          fight = true
        end
      end
    end
    if part ~= nil and part ~= 2 then return fight end
    for key, names in pairs(SCALE_NAMES) do
      if pending(f, 'scale:' .. key) then set_count(force, f, 'scale:' .. key, count_of(force, names)) end
    end
    if pending(f, 'scale:platforms') then
      local n = 0
      for _ in pairs(force.platforms) do n = n + 1 end
      set_count(force, f, 'scale:platforms', n)
    end
    if pending(f, 'scale:game_hours') then set_count(force, f, 'scale:game_hours', math.floor(game.tick / HOUR)) end
    return fight
  end
  function M.sweep(tick)
    if M.mode() == 'off' then return end
    local part = math.floor((tick or game.tick) / 600) % 4
    local fight = false
    for _, force in ipairs(api.forces()) do
      if M.sweep_force(force, part) then fight = true end
    end
    -- the fights still pending are known after the events part
    if part == 3 then pending_fight = fight end
  end

  -- The words of a condition: what opens a unit, in facts.
  local SAY = {
    ['event:enemy_seen']='your team has met enemies', ['event:spitters']='your team has met spitters or larger biters',
    ['event:worms']='a worm has fired at your team', ['event:attacked']='enemies have attacked your team\'s buildings',
    ['event:loss']='enemies have destroyed a building of your team', ['event:pollution_attack']='an attack group has formed',
    ['event:died']='an agent of your team has died', ['event:demolishers']='your team has met a demolisher',
    ['event:pentapods']='your team has met a pentapod', ['event:asteroids']='an asteroid has hit your team\'s platform',
    ['event:spoiled']='an item of your team has spoiled', ['event:low_power']='a network of your team has run on low or no power',
    ['event:second_surface']='your team has a platform or an agent on a second planet',
    ['event:freight']='a cargo pod of your team has landed', ['event:resource_depleted']='a patch your team mines has run out',
  }
  local HABIT = {hand_crafts='crafted %d of one recipe by hand', hand_belts='placed %d belts with build',
    hand_poles='placed %d electric poles with build', hand_feeds='made %d feed or refuel calls',
    chest_moves='made %d transfers at one container', walked='walked %d tiles', refused='had %d refused calls of this action',
    refused_builds='had %d placements refused', repeat_calls='made %d similar calls in a row', sleeps='made %d sleeps or waits',
    board_items='posted %d board items'}
  local SCALE = {machines='has %d machines', labs='has %d labs', drills='has %d mining drills', belts='has %d belts',
    inserters='has %d inserters', turrets='has %d turrets', platforms='has %d platforms', game_hours='has played %d game hours'}
  function M.say_atom(a)
    if SAY[a] then return SAY[a] end
    local kind, rest = a:match('^(%a+):(.*)$')
    if kind == 'research' then return 'your team has researched ' .. rest end
    if kind == 'built' then return 'your team has built ' .. rest:gsub('|', ' or ') end
    if kind == 'arrived' then return 'your team has an agent or a platform at ' .. rest end
    local name, n = (rest or ''):match('^(.-):(%d+)$')
    if kind == 'habit' and HABIT[name] then return 'your team has ' .. string.format(HABIT[name], tonumber(n)) end
    if kind == 'scale' and SCALE[name] then return 'your team ' .. string.format(SCALE[name], tonumber(n)) end
    return a
  end
  function M.why(c, world)
    for _, g in ipairs(c.g) do
      if not world[g] then return 'not part of this world (' .. g .. ' is off)' end
    end
    local parts = {}
    for _, a in ipairs(c.a) do
      if a == 'never' then return 'not available to agents' end
      parts[#parts+1] = M.say_atom(a)
    end
    return 'it opens when ' .. table.concat(parts, ', or when ')
  end

  -- The gate (runtime M.dispatch, before the call runs): a refusal text, or nil.
  function M.gate(request, force)
    if M.mode() ~= 'filter' or type(request) ~= 'table' or request.operator == true or request.reader ~= nil then return nil end
    local action = request.action
    if type(action) ~= 'string' or HOST[action] or not U.actions[action] then return nil end
    local c = U.actions[action]
    for _, a in ipairs(c.a) do if a == 'never' then return nil end end
    if root().refuse ~= true then return nil end
    local o = M.open_set(force)
    if not o.actions[action] then
      return action .. ' is not available yet: ' .. M.why(c, o.world) .. ' (the same rule for every team; ./fh help lists what is open)'
    end
    local t = U.args[action]
    if t and type(request.args) == 'table' then
      for arg in pairs(request.args) do
        if t[arg] and not o.args[action][arg] then
          return action .. '\'s argument ' .. arg .. ' is not available yet: ' .. M.why(t[arg], o.world)
        end
      end
    end
    return nil
  end
  function M.arg_hidden(force, action, arg)
    -- (the valid list of an unknown-argument refusal: documentation, so shut arguments stay out of it in both settings)
    return M.mode() == 'filter' and not M.arg_open(force, action, arg)
  end

  -- describe for an agent (runtime M.dispatch): only the open actions and arguments, the locked ones by name with
  -- their condition (refuse) or not at all (undocumented), and a bundle id carrying the revision.
  function M.describe_key(force, bundle)
    return tostring(bundle or 'folder') .. '@d' .. fstate(force).rev
  end
  function M.filter_describe(result, force, bundle)
    if M.mode() ~= 'filter' or type(result) ~= 'table' or type(result.actions) ~= 'table' then return result end
    local o = M.open_set(force)
    local out = {}
    for k, v in pairs(result) do out[k] = v end
    out.actions, out.locked = {}, {}
    local refuse = root().refuse == true
    for name, schema in pairs(result.actions) do
      local c = U.actions[name]
      local never = false
      for _, a in ipairs(c and c.a or {}) do if a == 'never' then never = true end end
      if not c or never or o.actions[name] then
        local t = U.args[name]
        if t then
          local s = {}
          for arg, text in pairs(schema) do if not t[arg] or o.args[name][arg] then s[arg] = text end end
          out.actions[name] = s
        else
          out.actions[name] = schema
        end
      elseif refuse then
        out.locked[name] = M.why(c, o.world)
      end
    end
    if not refuse or next(out.locked) == nil then out.locked = nil end
    out.bundle = M.describe_key(force, bundle)
    out.disclosure = M.counts_line(force)
    return out
  end
  function M.counts_line(force)
    local o = M.open_set(force)
    local n = {actions=0, docs=0}
    for name in pairs(o.actions) do
      local never = false
      for _, a in ipairs(U.actions[name].a) do if a == 'never' then never = true end end
      if not never then n.actions = n.actions + 1 end
    end
    for _ in pairs(o.docs) do n.docs = n.docs + 1 end
    return string.format('%d of %d actions and %d of %d reference entries open for your team', n.actions, TOTAL.actions,
      n.docs, TOTAL.docs)
  end

  -- The unlock line on an agent's reply: what opened since its last line, once (filter mode only).
  function M.reply_line(name, force)
    if M.mode() ~= 'filter' or type(name) ~= 'string' then return nil end
    local f = fstate(force)
    local told = f.told[name]
    if told == nil then f.told[name] = f.rev; return nil end
    if told >= f.rev then return nil end
    f.told[name] = f.rev
    local acts, args, docs, topics, seen = {}, 0, 0, {}, {}
    for i = #f.log, 1, -1 do
      local e = f.log[i]
      if e.rev > told then
        for _, a in ipairs(e.actions) do
          if not seen[a] then
            seen[a] = true
            acts[#acts+1] = a
            local t = U.actions[a] and U.actions[a].t
            if t and not topics[t] then topics[t] = true; topics[#topics+1] = t end
          end
        end
        args, docs = args + e.args, docs + e.docs
      end
    end
    if #acts == 0 and args == 0 and docs == 0 then return nil end
    local parts = {}
    -- newest first; what each does for the first 4, the names of the rest
    for i, a in ipairs(acts) do
      local w = i <= 4 and U.actions[a] and U.actions[a].w
      parts[#parts+1] = w and (a .. ' (' .. w .. ')') or a
    end
    -- (the reply's field is new: the line is what opened)
    local line = table.concat(parts, ', ')
    local more = {}
    if args > 0 then more[#more+1] = string.format('%d argument%s of open actions (./fh help ACTION)', args, args == 1 and '' or 's') end
    if docs > 0 then more[#more+1] = string.format('%d reference entr%s', docs, docs == 1 and 'y' or 'ies') end
    if #more > 0 then line = line .. (#acts > 0 and '; ' or '') .. table.concat(more, ' and ') end
    if #topics > 0 then
      local t = {}
      for _, x in ipairs(topics) do t[#t+1] = './fh help ' .. x end
      line = line .. '; docs: ' .. table.concat(t, ', ')
    end
    return line
  end

  -- disclosure {} (the host: fh help TOPIC, the brief): the caller's force's open set.
  M.schema.disclosure = {returns='the harness\'s own read for fh help and the brief: mode, rev, and with mode filter the '
    .. 'open and the shut action names, shut argument names by action, and open and shut reference entry ids (topic#key) '
    .. 'and brief item ids (file#key)'}
  function M.read(force)
    local mode = M.mode()
    local out = {mode=mode, refuse=root().refuse == true}
    if mode == 'off' then return out end
    local o = M.open_set(force)
    out.rev = fstate(force).rev
    if mode ~= 'filter' then return out end
    local function keys(t) local l = {} for k in pairs(t) do l[#l+1] = k end table.sort(l) return l end
    out.actions, out.docs, out.brief = keys(o.actions), keys(o.docs), keys(o.brief)
    out.args = {}
    for action, t in pairs(U.args) do
      local shut = {}
      for arg in pairs(t) do if not o.args[action][arg] then shut[#shut+1] = arg end end
      if #shut > 0 then table.sort(shut); out.args[action] = shut end
    end
    out.args_locked = out.args
    out.args = nil
    -- what is shut (the host and the brief show everything else: an entry added since this table was built stays open)
    out.actions_shut, out.docs_shut, out.brief_shut = {}, {}, {}
    for name, c in pairs(U.actions) do
      local never = false
      for _, x in ipairs(c.a) do if x == 'never' then never = true end end
      if not o.actions[name] and not never then out.actions_shut[#out.actions_shut+1] = name end
    end
    for id in pairs(U.docs) do if not o.docs[id] then out.docs_shut[#out.docs_shut+1] = id end end
    for id in pairs(U.brief) do if not o.brief[id] then out.brief_shut[#out.brief_shut+1] = id end end
    table.sort(out.actions_shut); table.sort(out.docs_shut); table.sort(out.brief_shut)
    out.line = M.counts_line(force)
    return out
  end

  -- Operator: disclosure_set {mode, refuse?, world?, reset?}; disclosure {force?, ids?}: each force's state (ids: its open
  -- names and ids, as the agents' read gives them: tools/disclosure/set.py saves them for the brief).
  function M.operator.disclosure_set(a)
    local d = root()
    if a.mode ~= nil then
      assert(a.mode == 'off' or a.mode == 'observe' or a.mode == 'filter', 'mode: off, observe or filter')
      d.mode = a.mode
    end
    if a.refuse ~= nil then d.refuse = a.refuse == true end
    if type(a.world) == 'table' then
      d.world = d.world or {}
      for k, v in pairs(a.world) do d.world[k] = v == true end
    end
    if a.reset == true then d.forces = {} end
    cache = {}
    if d.mode ~= 'off' then
      for _, force in ipairs(api.forces()) do M.sweep_force(force) end
    end
    return {mode=d.mode, refuse=d.refuse == true, world=d.world}
  end
  function M.operator.disclosure(a)
    local d = root()
    local out = {mode=d.mode, refuse=d.refuse == true, forces={}}
    -- off: nothing kept, so nothing to read (and no per-force table made by reading)
    if d.mode == 'off' then return out end
    for _, force in ipairs(api.forces()) do
      if a.force == nil or a.force == force.name then
        local f = fstate(force)
        local o = M.open_set(force)
        local n = {actions=0, args=0, docs=0, brief=0}
        for _ in pairs(o.actions) do n.actions = n.actions + 1 end
        for _, t in pairs(o.args) do for _ in pairs(t) do n.args = n.args + 1 end end
        for _ in pairs(o.docs) do n.docs = n.docs + 1 end
        for _ in pairs(o.brief) do n.brief = n.brief + 1 end
        local metl = {}
        for atom, tick in pairs(f.met) do metl[#metl+1] = {atom=atom, tick=tick} end
        table.sort(metl, function(x, y) return x.tick < y.tick or (x.tick == y.tick and x.atom < y.atom) end)
        local newest = {}
        for i = math.max(1, #f.log - 7), #f.log do newest[#newest+1] = f.log[i] end
        local next_ = {}
        for key, ts in pairs(thresholds) do
          if key:sub(1, 13) ~= 'habit:refused' then
            local low
            for v in pairs(ts) do if v > (f.counts[key] or 0) and (not low or v < low) then low = v end end
            if low then next_[#next_+1] = string.format('%s %d of %d', key, f.counts[key] or 0, low) end
          end
        end
        table.sort(next_)
        out.forces[force.name] = {rev=f.rev, world=o.world, open=n, total=TOTAL, met=metl, newest=newest, next=next_,
          ids=a.ids == true and M.read(force) or nil,
          line=string.format('%s: %d of %d actions, %d of %d advanced arguments, %d of %d reference entries open (rev %d)',
            force.name, n.actions, TOTAL.actions, n.args, TOTAL.args, n.docs, TOTAL.docs, f.rev)}
      end
    end
    return out
  end
  return M
end
